citation(eu_reg_2024_1774_art_6_2_c, [label - 'Delegated Regulation (EU) 2024/1774 (RTS) Art 6(2)(c): rules for encryption of internal network connections and traffic with external parties', ref - 'https://eur-lex.europa.eu/eli/reg_del/2024/1774/oj', verbatim - 'the encryption of internal network connections and traffic with external parties;']).
citation(eu_reg_2024_1774_art_6_2_d, [label - 'Delegated Regulation (EU) 2024/1774 (RTS) Art 6(2)(d): rules on cryptographic key management', ref - 'https://eur-lex.europa.eu/eli/reg_del/2024/1774/oj', verbatim - 'the cryptographic key management referred to in Article 7, laying down rules on the correct use, protection, and lifecycle of cryptographic keys.']).
citation(eu_reg_2024_1774_art_6_3, [label - 'Delegated Regulation (EU) 2024/1774 (RTS) Art 6(3): criteria for selecting cryptographic techniques, and mitigation where leading practices or standards are not followed', ref - 'https://eur-lex.europa.eu/eli/reg_del/2024/1774/oj', verbatim - 'criteria for the selection of cryptographic techniques and use practices']).
citation(eu_reg_2024_1774_art_6_4, [label - 'Delegated Regulation (EU) 2024/1774 (RTS) Art 6(4): updating the cryptographic technology, and mitigation where it is not updated', ref - 'https://eur-lex.europa.eu/eli/reg_del/2024/1774/oj', verbatim - 'provisions for updating or changing, where necessary, the cryptographic technology on the basis of developments in cryptanalysis.']).
