citation(eu_reg_2024_1774_art_7_2, [label - 'Delegated Regulation (EU) 2024/1774 (RTS) Art 7(2): controls to protect cryptographic keys and their design basis', ref - 'https://eur-lex.europa.eu/eli/reg_del/2024/1774/oj', verbatim - 'Financial entities shall identify and implement controls to protect cryptographic keys through their whole lifecycle against loss, unauthorised access, disclosure, and modification.']).
