citation(eu_reg_2024_1774_art_7_5, [label - 'Delegated Regulation (EU) 2024/1774 (RTS) Art 7(5): prompt renewal of certificates before expiration', ref - 'https://eur-lex.europa.eu/eli/reg_del/2024/1774/oj', verbatim - 'Financial entities shall ensure the prompt renewal of certificates in advance of their expiration.']).
